package net.civeira.phylax.feature.observe.observedissue.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class MergedIntoVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property merged into of observed issue ")
  void test_merged_into_v_o_builder() {
    Assertions.assertFalse(MergedIntoVO.nullValue().getMergedInto().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(MergedIntoVO.tryFrom(null).getMergedInto().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", MergedIntoVO.from("one").getMergedInto().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> MergedIntoVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", MergedIntoVO.from("one").toString());
  }
}
